<?php
namespace App\Livewire\Admin\Leave;use App\Enums\LeaveStatus;use App\Enums\LeaveType;use App\Models\Leave;use Livewire\Component;
class Create extends Component{public string $type='annual';public string $start_date='';public string $end_date='';public $hours=null;public string $description='';public function save(){$d=$this->validate(['type'=>['required','in:'.implode(',',array_keys(LeaveType::getOptions()))],'start_date'=>['required','date','after_or_equal:today'],'end_date'=>['required','date','after_or_equal:start_date'],'hours'=>['nullable','numeric','gt:0','max:24'],'description'=>['required','string','max:5000']]);$d+=['user_id'=>auth()->id(),'created_by'=>auth()->id(),'status'=>LeaveStatus::PENDING];Leave::create($d);session()->flash('success','Leave request submitted.');return $this->redirectRoute('admin.leave.index',navigate:true);}public function render(){return view('livewire.admin.leave.create',['types'=>LeaveType::getOptions()])->layout('components.layouts.admin',['title'=>'Request leave']);}}
